import{_ as n,C as t,c as r,o as s,aj as l,G as o,w as d}from"./chunks/framework.Bfdr4H5E.js";const c="/sk/images/TradingView-Indicators-Menu1.webp",h="/sk/images/TradingView-Indicators-Menu2.webp",g="/sk/images/Beverage-Seller.webp",u="/sk/images/TradingView-Invite-ver.webp",p="/sk/images/TradingView-Indicators-Favorite.webp",T=JSON.parse('{"title":"TradingView – Indicators","description":"","frontmatter":{"outline":"deep","prev":{"text":"TradingView – How to use Drawing Tools","link":"/trading-with-pav/tradingview-how-to-use-drawing-tools"},"next":{"text":"TradingView – Favorite Tools and Tricks","link":"/trading-with-pav/tradingview-favorite-tools-and-tricks"}},"headers":[],"relativePath":"trading-with-pav/tradingview-indicators.md","filePath":"trading-with-pav/tradingview-indicators.md"}'),m={name:"trading-with-pav/tradingview-indicators.md"};function v(f,e,w,y,b,k){const a=t("GraphComment"),i=t("ClientOnly");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="tradingview-–-indicators" tabindex="-1">TradingView – Indicators <a class="header-anchor" href="#tradingview-–-indicators" aria-label="Permalink to &quot;TradingView – Indicators&quot;">​</a></h1><p>In this article will look into TradingView – Indicators what are they? Types of ? Which indicators should be used etc.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#indicators">Indicators</a></li><li><a href="#what-is-an-indicator">What is an Indicator</a><ul><li><a href="#moving-averages">Moving Averages</a></li></ul></li><li><a href="#applying-indicators-in-tradingview">Applying indicators in TradingView</a></li><li><a href="#invite-only-scripts">Invite-only scripts</a></li><li><a href="#add-to-favorites">Add to favorites</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="indicators" tabindex="-1">Indicators <a class="header-anchor" href="#indicators" aria-label="Permalink to &quot;Indicators&quot;">​</a></h2><p>First lets open the indicators menu for that click on Indicators on the top menu and voila “<strong>Indicators, Metrics and Strategies</strong>” pops up. Image is show below.</p><p><img src="'+c+'" alt="TradingView-Indicators-Menu1"></p><p>As you can see in the image above the “<strong>Indicators</strong>” are listed in the “<strong>Technicals</strong>“. A technical indicator helps a trader analyze the price movement of a security.</p><p><strong>Quick Tip for learning any new indicator.</strong><br> Lets say you want to learn what the 24-hour Volume is about. In the image above you can see the 24-hour Volume highlighted and you can see on the right side of the 24-hour Volume a grey circle with question mark. If you click on it you can see the description of the indicator i.e. Definition, Calculation, What to look for, Inputs, Examples etc. You can see in the image below</p><p><img src="'+h+'" alt="TradingView-Indicators-Menu2"></p><p>As you know we use less indicators in our trading and as you progress through our course article you will know why is this but in short the ones we use are for only conforming the already decided future direction through our Price Action analysis.</p><p>So if you are not taken this course <a href="/sk/trading-with-pav-course/">Click Here</a> to check syllabus for our trading course called Trading with PAV and Enroll NOW. Also if you don’t need the course and are already achieved consistent profitability in trading check our <a href="/sk/volume-profile-tools/">Volume Profile &amp; VWAP tools</a> to get an edge in market with our custom built Indicators. Now lets get to know what is Indicator.</p><h2 id="what-is-an-indicator" tabindex="-1">What is an Indicator <a class="header-anchor" href="#what-is-an-indicator" aria-label="Permalink to &quot;What is an Indicator&quot;">​</a></h2><p>Indicators are quantitative analysis tools used to interpret stocks or current status and future trends in the stock market. They are mathematical formulas and ratios used to predict how the market will move based on applying a statistical formula to a set of data points to make conclusions on market movements.</p><h3 id="moving-averages" tabindex="-1">Moving Averages <a class="header-anchor" href="#moving-averages" aria-label="Permalink to &quot;Moving Averages&quot;">​</a></h3><p>Lets take a example of an indicator called Moving Averages. Before we learn moving averages, let us have a quick recap on how averages are calculated.</p><p><img src="'+g+'" alt="Beverage-Seller"></p><p>Assume 5 people are sitting on a nice sunny beach enjoying a nice chilled bottled beverage. The sun is so bright and nice that each one of them ends up drinking several bottles of the beverage. Assume the final count to be something like this:</p><table tabindex="0"><thead><tr><th>Sr No</th><th>Person</th><th>No of Bottles</th></tr></thead><tbody><tr><td>01</td><td>A</td><td>07</td></tr><tr><td>02</td><td>B</td><td>05</td></tr><tr><td>03</td><td>C</td><td>06</td></tr><tr><td>04</td><td>D</td><td>03</td></tr><tr><td>05</td><td>E</td><td>08</td></tr><tr><td>Total no of bottles consumed</td><td></td><td>29</td></tr></tbody></table><p>Assume a 6th person walks in to find out 29 bottles of beverages lying around them. He can quickly get a sense of ‘roughly’ how many bottles each of them consumed by dividing <strong>[the total number of bottles]</strong>  by <strong>[total number of people]</strong>.</p><p>In this case, it would be:</p><p>=29/5<br> =5.8 bottles per head.</p><p>So, the average, in this case, tells us roughly how many bottles each person had consumed. Obviously, there would be few of them who had consumed above and below the average. For example, Person E drank 8 bottles of beverage, which is way above the average of 5.8 bottles. Likewise, person D drank just 3 bottles of beverage, which is way below the average of 5.8 bottles. Therefore the average is just an estimate, and one cannot expect it to be accurate.</p><p>Extending the concept to stocks, here are the closing prices of ITC Limited for the last 5 trading sessions. The last 5-day average close would be calculated as follows:</p><table tabindex="0"><thead><tr><th>Date</th><th>Closing Price</th></tr></thead><tbody><tr><td>17/10/22</td><td>344.95</td></tr><tr><td>18/10/22</td><td>342.35</td></tr><tr><td>19/10/22</td><td>344.20</td></tr><tr><td>20/10/22</td><td>344.25</td></tr><tr><td>21/10/22</td><td>344.0</td></tr><tr><td>Total</td><td>1719.75</td></tr></tbody></table><p>= <strong>1719.75 / 5</strong>= 343.95</p><p>Hence the average closing price of ITC over the last 5 trading sessions is 343.95.</p><p>We are essentially moving to the latest data point and discarding the oldest to calculate the latest 5-day average. Hence the name “moving” average!</p><p>In the above example, the calculation of the moving average is based on the closing prices.  Sometimes, moving averages are also calculated using other parameters such as high, low, and open. However, the closing prices are used mostly by the traders and investors as it reflects the price at which the market finally settles down.</p><p>Moving averages can be calculated for any time frame, from minutes, hours to years.  Any time frame can be selected from the charting software-based of your requirements.</p><h2 id="applying-indicators-in-tradingview" tabindex="-1">Applying indicators in TradingView <a class="header-anchor" href="#applying-indicators-in-tradingview" aria-label="Permalink to &quot;Applying indicators in TradingView&quot;">​</a></h2><ol><li>Lets go to TradingView and Open the chart of SBIN 1D timeframe.</li><li>Click on Indicators in the top menu.</li><li>Select “<strong>Technicals</strong>” and in right make sure you are in “<strong>Indicators</strong>” tab.</li><li>Search for “<strong>Moving Average</strong>” the list is alphabetically listed.</li><li>After you find it yo can even read the description on clicking right side question mark or else click on it.</li><li>Close the indicator panel and voila. Below the volume Indicator in the status bar section you can see the “<strong>MA 9 close 0 SMA 5</strong>” what this means is that Moving Average is set on length 9 and source for calculation is <strong>Close</strong> and line offset on is set to 0 also SMA mean Smoothing MA line length is 5. This information is helpful for quick glance on what setting are in place.</li><li>Now hover over the “<strong>MA 9 close 0 SMA 5</strong>” in status line you will see options like <strong>eye</strong> which hides the MA from chart, <strong>Gear</strong> ⚙️ which opens settings, <strong>{ }</strong> which opens the Source code for MA, <strong>X</strong> which removes the indicator from chart, <strong>···</strong> which opens a menu (imp from this menu are Alert and visual order to bring in front or back of the candlestick chart)</li><li>Clicking on Gear icon open settings panel for MA you can change the “<strong>Inputs</strong>” which we see at glance in the status line “<strong>MA 9 close 0 SMA 5</strong>“</li><li>Clicking on “<strong>Style</strong>” lets you change MA line color, width and how should it be displayed.</li><li>All the above structure is same for all indicators, change is only in indicators working, inputs, style etc. If you get stuck you always have (?) Show description on the right side of every indicator that you can learn from.</li></ol><h2 id="invite-only-scripts" tabindex="-1">Invite-only scripts <a class="header-anchor" href="#invite-only-scripts" aria-label="Permalink to &quot;Invite-only scripts&quot;">​</a></h2><p>If you have bought the course “<a href="/sk/trading-with-pav-course/">Trading with PAV</a>” or the “<a href="/sk/volume-profile-tools/">Volume Profile tools</a>” you get our custom built <strong>Volume Profile – Flexible</strong>, <strong>VWAP</strong>, <strong>Volume Profile PLUS – Vol based S/R Zone</strong>s and some <strong>BONUS</strong> indicators which are <strong>Rejection Candles – with volume</strong>, <strong>Relative Strength Index – Custom RSI</strong>, <strong>Multi-Time Period Charts</strong>, <strong>Volume Indicator: Future vol on Spot</strong>.</p><p>All these are activated by us when your billing is conformed and then there is one more option activated i.e. “<strong>Invite-only scripts</strong>” in the indicators pop up. If you haven’t purchased you wont see it. Look at the below image.</p><p><img src="'+u+'" alt="TradingView-Invite-ver"></p><p>As you can see in the above image all the above mentioned indicators are included by us for lifetime. How to use each “<strong>indicators</strong>” from the “<strong>Invite-only scripts</strong>” you will learn later also strategies based on these will be in coming articles which will be only available to our traders who purchased.</p><h2 id="add-to-favorites" tabindex="-1">Add to favorites <a class="header-anchor" href="#add-to-favorites" aria-label="Permalink to &quot;Add to favorites&quot;">​</a></h2><p>In the above image of “<strong>Invite-only scripts</strong>” you can see star on the highlighted indicator called “<strong>Multi-Time Period Charts</strong> <strong>YSTC</strong>“. If you click on the star it is added to favorites. Star all the 8 listed indicators and you can easily access them from top menu drop-down menu near indicators. See the image below.</p><p><img src="'+p+'" alt="TradingView-Indicators-Favorite"></p><p>As you can see you can quickly select any indicator quickly use and remove it from chart. You can favorite any indicator you like and as TradingView’s Free account has a limit of displaying 3 indicators you can use favorite to your advantage. That’s it for this article on indicators.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',41)),o(i,null,{default:d(()=>[o(a)]),_:1})])}const A=n(m,[["render",v]]);export{T as __pageData,A as default};
